    ("历史", "中国历史上第一个统一的中央集权的封建王朝是？", "秦朝", ["汉朝", "周朝", "夏朝"], "公元前 221 年秦灭六国，建立第一个统一的多民族封建国家。"),
    ("历史", "公元前 221 年完成统一六国大业的是？", "嬴政（秦始皇）", ["刘邦", "项羽", "李世民"], "秦王嬴政先后灭掉六国，自称始皇帝。"),
    ("历史", "“文景之治”出现在我国哪个朝代？", "西汉", ["东汉", "唐朝", "宋朝"], "汉文帝、汉景帝推行休养生息政策，史称文景之治。"),
    ("历史", "张骞出使西域为哪条著名商路的开通奠定了基础？", "丝绸之路", ["海上丝绸之路", "茶马古道", "京杭大运河"], "张骞两次出使西域，沟通了中原与西域，开辟丝绸之路。"),
    ("历史", "唐太宗统治时期出现的治世局面被称为？", "贞观之治", ["开元盛世", "文景之治", "康乾盛世"], "唐太宗年号贞观，政治清明、经济发展，史称贞观之治。"),
    ("历史", "开创“开元盛世”局面的皇帝是？", "唐玄宗", ["唐太宗", "武则天", "唐高祖"], "唐玄宗统治前期年号开元，唐朝进入全盛时期。"),
    ("历史", "唐朝时六次东渡日本、传播中华文化的高僧是？", "鉴真", ["玄奘", "一行", "张骞"], "鉴真应日本邀请六次东渡，传播佛教和建筑、医药等文化。"),
    ("历史", "玄奘西行取经的目的地“天竺”是今天的哪里？", "印度", ["日本", "伊朗", "意大利"], "天竺即古印度，玄奘取经归来后口述了《大唐西域记》。"),
    ("历史", "北宋时发明活字印刷术的是？", "毕昇", ["蔡伦", "沈括", "张衡"], "毕昇发明泥活字印刷术，比欧洲早约 400 年。"),
    ("历史", "东汉时改进造纸术的是？", "蔡伦", ["毕昇", "张衡", "鲁班"], "蔡伦改进造纸术，用树皮、破布等为原料，纸得以推广。"),
    ("历史", "元朝时来华并著有《马可·波罗行纪》的意大利旅行家是？", "马可·波罗", ["利玛窦", "汤若望", "哥伦布"], "马可·波罗在元朝时来到中国，其行纪激起欧洲人对东方的向往。"),
    ("历史", "明朝郑和七下西洋，最远到达？", "红海沿岸和非洲东海岸", ["地中海沿岸", "美洲大陆", "欧洲大西洋沿岸"], "1405—1433 年郑和七下西洋，最远到达非洲东海岸和红海沿岸。"),
    ("历史", "明朝抗击倭寇的民族英雄是？", "戚继光", ["郑成功", "岳飞", "林则徐"], "戚继光率戚家军在东南沿海抗击倭寇，基本肃清倭患。"),
    ("历史", "1662 年从荷兰殖民者手中收复台湾的是？", "郑成功", ["戚继光", "康熙帝", "施琅"], "郑成功 1662 年打败荷兰殖民者，使台湾回到祖国怀抱。"),
    ("历史", "我国科举制度正式创立于哪个朝代？", "隋朝", ["唐朝", "汉朝", "宋朝"], "隋炀帝时设进士科，标志着科举制度正式形成。"),
    ("历史", "采纳“罢黜百家，尊崇儒术”建议的皇帝是？", "汉武帝", ["秦始皇", "汉文帝", "唐太宗"], "汉武帝采纳董仲舒建议，把儒家学说立为正统思想。"),
    ("历史", "北魏孝文帝改革的核心内容是？", "推行汉化政策，迁都洛阳", ["推行郡县制", "废除分封制", "实行重农抑商"], "孝文帝迁都洛阳，推行说汉语、穿汉服、改汉姓等措施。"),
    ("历史", "贯通南北的隋朝大运河开凿于哪位皇帝在位时期？", "隋炀帝", ["隋文帝", "唐太宗", "唐玄宗"], "隋炀帝下令开凿大运河，以洛阳为中心，贯通南北。"),
    ("历史", "鸦片战争爆发于哪一年？", "1840 年", ["1839 年", "1842 年", "1856 年"], "1840 年英国发动鸦片战争，是中国近代史的开端。"),
    ("历史", "中国近代史上第一个不平等条约是？", "《南京条约》", ["《马关条约》", "《辛丑条约》", "《北京条约》"], "1842 年签订的《南京条约》是近代第一个不平等条约。"),
    ("历史", "《南京条约》中清政府被迫割让的领土是？", "香港岛", ["台湾全岛", "九龙司地方一区", "辽东半岛"], "《南京条约》割香港岛给英国；台湾是《马关条约》割让的。"),
    ("历史", "甲午中日战争后，清政府被迫签订的条约是？", "《马关条约》", ["《南京条约》", "《辛丑条约》", "《天津条约》"], "1895 年甲午战败后签订《马关条约》，大大加深了半殖民地化。"),
    ("历史", "使中国完全沦为半殖民地半封建社会的条约是？", "《辛丑条约》", ["《马关条约》", "《南京条约》", "《北京条约》"], "1901 年《辛丑条约》签订，清政府完全成为列强统治工具。"),
    ("历史", "辛亥革命爆发于哪一年？", "1911 年", ["1919 年", "1912 年", "1901 年"], "1911 年 10 月 10 日武昌起义爆发，因是辛亥年，故称辛亥革命。"),
    ("历史", "辛亥革命的主要领导人是？", "孙中山", ["黄兴", "袁世凯", "康有为"], "孙中山领导辛亥革命，推翻了清朝统治和两千多年君主专制。"),
    ("历史", "中华民国成立于哪一年？", "1912 年", ["1911 年", "1919 年", "1921 年"], "1912 年 1 月 1 日中华民国临时政府在南京成立。"),
    ("历史", "五四运动爆发于哪一年？", "1919 年", ["1911 年", "1921 年", "1912 年"], "1919 年 5 月 4 日北京学生游行示威，五四运动爆发。"),
    ("历史", "五四运动爆发的直接导火索是？", "巴黎和会上中国外交的失败", ["九一八事变", "袁世凯称帝", "七七事变"], "巴黎和会把德国在山东的权益转让给日本，引发五四运动。"),
    ("历史", "中国共产党成立于哪一年？", "1921 年", ["1919 年", "1927 年", "1949 年"], "1921 年 7 月中共一大召开，标志着中国共产党诞生。"),
    ("历史", "中华人民共和国成立于哪一天？", "1949 年 10 月 1 日", ["1945 年 8 月 15 日", "1949 年 1 月 1 日", "1950 年 10 月 1 日"], "1949 年 10 月 1 日开国大典举行，中华人民共和国成立。"),
    # ===== 地理 =====
    ("地理", "我国共有多少个省级行政区？", "34 个", ["32 个", "33 个", "35 个"], "我国有 23 个省、5 个自治区、4 个直辖市和 2 个特别行政区。"),
    ("地理", "我国面积最大的省级行政区是？", "新疆维吾尔自治区", ["西藏自治区", "内蒙古自治区", "青海省"], "新疆面积约 166 万平方千米，约占全国陆地面积的六分之一。"),
    ("地理", "长江发源于？", "青藏高原的唐古拉山脉", ["巴颜喀拉山脉", "昆仑山脉", "喜马拉雅山脉"], "长江发源于唐古拉山，黄河发源于巴颜喀拉山，注意区分。"),
    ("地理", "黄河最终注入哪个海？", "渤海", ["黄海", "东海", "南海"], "黄河在山东注入渤海，是我国第二长河。"),
    ("地理", "我国地势第一级阶梯上最主要的地形区是？", "青藏高原", ["内蒙古高原", "塔里木盆地", "东北平原"], "第一级阶梯以青藏高原为主体，平均海拔 4000 米以上。"),
    ("地理", "我国地势的总体特点是？", "西高东低，呈三级阶梯状分布", ["东高西低", "南高北低", "中间高四周低"], "西高东低的地势使我国许多大河自西向东流入海洋。"),
    ("地理", "有“世界屋脊”之称的高原是？", "青藏高原", ["帕米尔高原", "巴西高原", "内蒙古高原"], "青藏高原平均海拔 4000 米以上，是世界最高的高原。"),
    ("地理", "我国面积最大的盆地是？", "塔里木盆地", ["准噶尔盆地", "四川盆地", "柴达木盆地"], "塔里木盆地位于新疆南部，是我国最大的盆地。"),
    ("地理", "我国面积最大的平原是？", "东北平原", ["华北平原", "长江中下游平原", "关中平原"], "东北平原是我国最大的平原，以肥沃的黑土著称。"),
    ("地理", "素有“天府之国”美称的是？", "四川盆地（成都平原）", ["长江中下游平原", "华北平原", "珠江三角洲"], "成都平原土壤肥沃、灌溉便利，自古有天府之国的美誉。"),
    ("地理", "秦岭—淮河一线是我国重要的地理分界线，它是？", "南方地区与北方地区的分界线", ["季风区与非季风区的分界线", "人口地理分界线", "第一、二级阶梯分界线"], "秦岭—淮河与 1 月 0℃ 等温线、800 毫米等降水量线大致吻合。"),
    ("地理", "我国的人口地理分界线是？", "黑河—腾冲一线", ["秦岭—淮河一线", "大兴安岭—太行山一线", "长江一线"], "黑河—腾冲一线东南人口稠密，西北人口稀疏。"),
    ("地理", "我国冬季气温分布的特点是？", "南北温差大，越往北气温越低", ["全国普遍高温", "南北温差很小", "越往北越暖和"], "冬季受纬度和冬季风影响，南北温差可达 50℃ 左右。"),
    ("地理", "北京的气候类型属于？", "温带季风气候", ["温带大陆性气候", "亚热带季风气候", "高原山地气候"], "北京夏季高温多雨、冬季寒冷干燥，属温带季风气候。"),
    ("地理", "我国降水的空间分布规律是？", "从东南沿海向西北内陆递减", ["从西北向东南递减", "全国各地均匀分布", "南方少、北方多"], "受夏季风影响，降水从东南沿海向西北内陆逐渐减少。"),
    ("地理", "北回归线没有穿过下列我国哪个省级行政区？", "海南省", ["云南省", "广西壮族自治区", "台湾省"], "北回归线自西向东穿过云南、广西、广东、台湾。"),
    ("地理", "我国少数民族中人口最多的是？", "壮族", ["回族", "满族", "维吾尔族"], "壮族是我国人口最多的少数民族，主要分布在广西。"),
    ("地理", "首都北京位于哪个地形区的北部边缘？", "华北平原", ["东北平原", "黄土高原", "内蒙古高原"], "北京位于华北平原北部，背靠燕山，面向渤海。"),
    ("地理", "日本的首都是？", "东京", ["大阪", "京都", "横滨"], "东京是日本首都和最大城市，位于本州岛。"),
    ("地理", "法国的首都是？", "巴黎", ["伦敦", "柏林", "罗马"], "巴黎是法国首都；伦敦是英国首都，柏林是德国首都。"),
    ("地理", "埃及的首都是？", "开罗", ["亚历山大", "卢克索", "悉尼"], "开罗是埃及首都，也是非洲最大的城市。"),
    ("地理", "澳大利亚的首都是？", "堪培拉", ["悉尼", "墨尔本", "珀斯"], "堪培拉是澳大利亚首都，悉尼是最大城市但不是首都。"),
    ("地理", "世界上面积最大的国家是？", "俄罗斯", ["加拿大", "中国", "美国"], "俄罗斯面积约 1700 万平方千米，居世界第一位。"),
    ("地理", "世界上面积最大的热带雨林分布在？", "南美洲的亚马孙平原", ["非洲的刚果盆地", "东南亚的马来群岛", "澳大利亚北部"], "亚马孙平原分布着世界上面积最大的热带雨林。"),
    ("地理", "世界最高峰珠穆朗玛峰位于哪条山脉？", "喜马拉雅山脉", ["昆仑山脉", "阿尔卑斯山脉", "安第斯山脉"], "珠峰海拔 8848.86 米，位于中尼边境的喜马拉雅山脉。"),
    ("地理", "划分南北半球的界线是？", "赤道（0°纬线）", ["本初子午线", "北回归线", "180°经线"], "赤道以北为北半球，以南为南半球。"),
    ("地理", "划分东西半球的经线圈是？", "20°W 和 160°E", ["0° 和 180°", "90°E 和 90°W", "20°E 和 160°W"], "为避免把欧洲、非洲分在两个半球，用 20°W 和 160°E 划分。"),
    ("地理", "全球共划分为多少个时区？", "24 个", ["12 个", "36 个", "48 个"], "全球按经度每 15° 划分为一个时区，共 24 个。"),
    ("地理", "北京位于东八区，伦敦位于中时区，两地相差几个小时？", "8 个小时", ["7 个小时", "9 个小时", "12 个小时"], "相邻时区相差 1 小时，东八区比中时区早 8 个小时。"),
    ("地理", "地球自转产生的地理现象是？", "昼夜交替和时间差异", ["四季变化", "昼夜长短变化", "五带的划分"], "自转产生昼夜交替，四季变化和五带是公转产生的。"),
    # ===== 安全 =====
    ("安全", "遭遇校园欺凌时，正确的做法是？", "及时告诉老师、家长或报警求助", ["忍气吞声不敢说", "找人殴打报复回去", "独自默默承受"], "及时求助才能有效制止欺凌，沉默和以暴制暴都不可取。"),
    ("安全", "发现有人触电，首先应该做的是？", "迅速切断电源或用干燥木棒挑开电线", ["直接用手拉开触电者", "向触电者泼水", "大声呼喊原地等待"], "直接用手拉会导致自己也触电，必须先断电或用绝缘物挑开电线。"),
    ("安全", "火灾中被困室内、烟雾弥漫时，正确的逃生方式是？", "用湿毛巾捂住口鼻，低姿匍匐前进", ["乘坐电梯快速下楼", "大声呼喊并直立奔跑", "躲进衣柜里等待"], "湿毛巾可过滤烟雾，低姿可减少吸入有毒烟气；火灾时不能用电梯。"),
    ("安全", "我国的火警报警电话是？", "119", ["110", "120", "122"], "119 是火警，110 是报警，120 是急救，122 是交通事故报警。"),
    ("安全", "需要紧急医疗救助时，应拨打的电话是？", "120", ["119", "110", "12315"], "120 是医疗急救电话，拨打时说清地点和病情。"),
    ("安全", "陌生网友提出线下见面，正确的做法是？", "拒绝见面，或先告知家长并征得同意", ["独自按时前往赴约", "带上贵重物品以示诚意", "相信网友一定不会骗自己"], "网络交往要增强自我保护意识，见网友须家长知情陪同。"),
    ("安全", "网上收到“中奖需先交手续费”的信息，应该？", "判定为诈骗，不理睬并举报", ["按要求先转账领奖", "提供银行卡号和密码", "先交一半手续费试试"], "凡是要先交钱的中奖信息都是诈骗，切勿转账和泄露密码。"),
    ("安全", "关于个人信息保护，正确的做法是？", "妥善保护，不随意在网上泄露", ["为领奖品随意填写真实信息", "把家庭住址发给陌生网友", "在公共平台公开身份证号"], "身份证号、住址、密码等属于个人信息，泄露可能被不法分子利用。"),
    ("安全", "运动中不小心扭伤脚踝，现场正确的处理是？", "立即停止运动，冷敷并抬高患肢", ["立即热敷和用力按摩", "忍着疼痛继续活动", "用力揉搓肿胀部位"], "扭伤后 48 小时内应冷敷止血消肿，热敷按摩会加重肿胀。"),
    ("安全", "游泳时小腿突然抽筋，正确的做法是？", "保持镇静，仰浮水面并牵拉抽筋部位", ["拼命挣扎呼救", "快速游向深水区", "惊慌大喊导致呛水"], "保持冷静仰浮可节省体力，反向牵拉抽筋的肌肉能缓解痉挛。"),
    ("安全", "过马路时正确的做法是？", "走人行横道，遵守信号灯，先左看后右看", ["红灯时快速跑过去", "翻越道路中间的护栏", "边低头玩手机边过马路"], "遵守交通规则、走斑马线是保障行人安全的基本要求。"),
    ("安全", "发现有人溺水，未成年人的正确做法是？", "大声呼救、拨打报警电话，用竹竿等物施救，不盲目下水", ["立即跳入水中救人", "手拉手结成人链下水", "站在岸边围观等待"], "未成年人下水救人或结成人链极易发生群体溺水，应智慧救援。"),
